# ------------------------------------------------------------------ models
def _load_bundle():
    path = Path(__file__).resolve().parent / "hm_lgbm_bundle.pkl"
    if not path.exists():
        return None
    try:
        import joblib
        b = joblib.load(path)
        return b if isinstance(b, dict) else None
    except Exception:
        return None


class BatteryAgent:
    """Política MPC-LP per a la bateria HARD MODE (6 MWh / ±1.500 kW)."""

    def __init__(self):
        self.cap = float(SPEC_CAP)
        self.power = float(SPEC_POWER)
        self.eta_c = float(SPEC_EFF) ** 0.5
        self.eta_d = float(SPEC_EFF) ** 0.5
        self.soc_min = 0.0
        self.last_ts = None
        self.precharge_gate = True

        self.forecast_mode = FORECAST_MODE
        self.net_mode = NET_MODE
        self._bundle = _load_bundle() if self.forecast_mode == "lgbm" else None
        if self._bundle is None:
            self.forecast_mode = "profiles"
            self.net_mode = "load_pv"

        # estat dels denominadors en línia
        self._hours_seen = 0
        self._acc_bco2 = 0.0
        self._acc_bcost = 0.0
        self._last_price = None
        self._last_co2 = None
        # memòria del dia
        self._day_mem = {}

    # ---------------------------------------------------------------- utils
    @staticmethod
    def _safe(value, default=0.0):
        try:
            v = float(value)
            return v if np.isfinite(v) else default
        except (TypeError, ValueError):
            return default

    @staticmethod
    def _parse_ts(value):
        if isinstance(value, str):
            return datetime.fromisoformat(value)
        if isinstance(value, datetime):
            return value
        try:
            import pandas as pd
            return pd.Timestamp(value).to_pydatetime()
        except Exception:
            raise ValueError(f"timestamp no interpretat: {value!r}")

    def _days_remaining(self, ts):
        return calendar.monthrange(ts.year, ts.month)[1] - ts.day + 1

    def _read_dims(self, obs):
        cap = self._safe(obs.get("cap_max_kwh"), None)
        if cap is None:
            soc = self._safe(obs.get("soc_kwh"), None)
            pct = self._safe(obs.get("soc_pct"), None)
            cap = (soc / pct) if (soc and pct) else self.cap
        power = self._safe(obs.get("power_max_kw"), self.power)
        return float(cap), float(power)

    def _window(self, obs):
        pa = self._safe(obs.get("preu_actual"), 0.1)
        ca = self._safe(obs.get("co2_actual"), 0.1)
        prices = obs.get("preus_properes_24h")
        co2s = obs.get("co2_properes_24h")
        if prices is None or len(prices) == 0:
            prices = [pa]
        if co2s is None or len(co2s) == 0:
            co2s = [ca]
        p = np.array([self._safe(x, pa) for x in prices], float)
        c = np.array([self._safe(x, ca) for x in co2s], float)
        return np.clip(p, 0.0, 2.0), np.clip(c, 0.0, 2.0)

    def _clamp(self, action, soc, cap, power):
        space = max(0.0, cap - float(soc))
        energy = max(0.0, float(soc))
        max_c = max(0.0, min(power, space / self.eta_c - EPS_CLAMP))
        max_d = max(0.0, min(power, energy * self.eta_d - EPS_CLAMP))
        a = float(action)
        if not np.isfinite(a):
            return 0.0
        a = max(-max_d, min(max_c, a))
        return 0.0 if abs(a) < 1e-9 else float(a)

    def _guard(self, action, net_avail, power):
        lim = max(0.0, float(net_avail))
        if lim < power and action < -lim:
            return -lim
        return action

    # -------------------------------------------------------- denominadors
    def _denominators(self, ts, tel, prices, co2s):
        days_remaining = self._days_remaining(ts)
        new_week = (days_remaining == TEST_DAYS and ts.hour == 0)
        cont = (self.last_ts is not None
                and ts == self.last_ts + timedelta(hours=1)
                and not new_week)
        if not cont:
            self._hours_seen = 0
            self._acc_bco2 = 0.0
            self._acc_bcost = 0.0
            self._last_price = None
        self._hours_seen += 1
        load_last = self._safe(tel.get("ultim_consum_kw"), None)
        pv_last = self._safe(tel.get("ultima_solar_kw"), 0.0)
        net_obs = None if load_last is None else max(0.0, load_last - pv_last)
        if self._hours_seen == 1 or self._last_price is None:
            self._acc_bco2 += (net_obs or 0.0) * float(co2s[0])
            self._acc_bcost += (net_obs or 0.0) * float(prices[0])
        else:
            self._acc_bco2 += (net_obs or 0.0) * float(self._last_co2)
            self._acc_bcost += (net_obs or 0.0) * float(self._last_price)
        self._last_price = float(prices[0])
        self._last_co2 = float(co2s[0])
        frac = min(self._hours_seen, WEEK_HOURS) / float(WEEK_HOURS)
        est_co2 = self._acc_bco2 + (1.0 - frac) * DCO2_MONTH[ts.month - 1]
        est_cost = self._acc_bcost + (1.0 - frac) * DCOST_MONTH[ts.month - 1]
        return max(est_co2, 1e-9), max(est_cost, 1e-9)

    # ------------------------------------------------------------- memòria
    def _remember(self, ts, tel, prices, co2s):
        try:
            is_first = self._last_price is None
            obs_ts = ts if is_first else (ts - timedelta(hours=1))
            key = obs_ts.date()
            for k in list(self._day_mem.keys()):
                if k != key:
                    del self._day_mem[k]
            lst = self._day_mem.setdefault(key, [])
            irr_prof_prev = float(IRR_PROF[obs_ts.month - 1, obs_ts.hour])
            irr_last = tel.get("irradiancia_wm2")
            ratio_irr = (float(irr_last) / irr_prof_prev) if (irr_prof_prev > 50.0 and irr_last is not None) else None
            we = 1 if obs_ts.weekday() >= 5 else 0
            pprof = float(PRICE_PROF[obs_ts.month - 1, obs_ts.hour, we])
            cprof = float(CO2_PROF[obs_ts.month - 1, obs_ts.hour, we])
            price_h = float(prices[0]) if is_first else self._last_price
            co2_h = float(co2s[0]) if is_first else self._last_co2
            lst.append((obs_ts.hour,
                        ratio_irr,
                        (price_h / pprof) if (pprof > 1e-4 and price_h) else None,
                        (co2_h / cprof) if (cprof > 1e-4 and co2_h) else None))
        except Exception:
            pass

    def _day_factors(self, ts):
        try:
            lst = self._day_mem.get(ts.date(), [])
            irrs = [r for _, r, _, _ in lst if r is not None]
            return float(np.mean(irrs)) if irrs else None, len(lst)
        except Exception:
            return None, 0

    # ---------------------------------------------------------- prediccions
    def _predict(self, ts, tel, prices, co2s):
        H = HORIZON
        Hk = len(prices)
        prev = ts - timedelta(hours=1)

        # factor meteo: última hora + mitjana diürna del dia
        wf_last = 1.0
        irr_prof_prev = float(IRR_PROF[prev.month - 1, prev.hour])
        irr_last = self._safe(tel.get("irradiancia_wm2"), None)
        if irr_last is not None and irr_prof_prev > 50.0:
            wf_last = float(np.clip(irr_last / irr_prof_prev, 0.25, 1.25))
        wf_day, n_obs = self._day_factors(ts)
        if wf_day is not None and n_obs >= 2:
            wf = float(np.clip(0.6 * wf_day + 0.4 * wf_last, 0.25, 1.25))
        else:
            wf = wf_last

        if self.forecast_mode == "lgbm" and self._bundle is not None:
            return self._predict_lgbm(ts, tel, prices, co2s, wf, H, Hk)
        return self._predict_profiles(ts, tel, prices, co2s, wf, H, Hk)

    def _predict_profiles(self, ts, tel, prices, co2s, wf, H, Hk):
        """Predicció per perfils mensuals + ratio de les hores conegudes."""
        pp3 = list(prices[:3]) + [prices[-1]] * max(0, 3 - len(prices[:3]))
        cc3 = list(co2s[:3]) + [co2s[-1]] * max(0, 3 - len(co2s[:3]))
        prof_p_k, prof_c_k = [], []
        for i in range(min(3, Hk)):
            t = ts + timedelta(hours=i)
            we = 1 if t.weekday() >= 5 else 0
            prof_p_k.append(float(PRICE_PROF[t.month - 1, t.hour, we]))
            prof_c_k.append(float(CO2_PROF[t.month - 1, t.hour, we]))
        ratio_p = float(np.clip(np.mean(pp3) / max(np.mean(prof_p_k), 1e-6), 0.6, 1.5))
        ratio_c = float(np.clip(np.mean(cc3) / max(np.mean(prof_c_k), 1e-6), 0.6, 1.5))

        price_hat = np.zeros(H)
        co2_hat = np.zeros(H)
        net_hat = np.zeros(H)
        load_last = self._safe(tel.get("ultim_consum_kw"), None)
        prev = ts - timedelta(hours=1)
        we_p = 1 if prev.weekday() >= 5 else 0
        lprof_prev = float(LOAD_PROF[prev.month - 1, prev.hour, we_p])
        bias = float(np.clip(load_last - lprof_prev, -400.0, 400.0)) \
            if (load_last is not None and lprof_prev > 100.0) else 0.0
        for i in range(H):
            t = ts + timedelta(hours=i)
            we = 1 if t.weekday() >= 5 else 0
            dec = 0.9 ** max(0, i - Hk + 1)
            price_hat[i] = PRICE_PROF[t.month - 1, t.hour, we] * (1.0 + (ratio_p - 1.0) * dec)
            co2_hat[i] = CO2_PROF[t.month - 1, t.hour, we] * (1.0 + (ratio_c - 1.0) * dec)
            pv_i = PV_PROF_MED[t.month - 1, t.hour] * (1.0 + (wf - 1.0) * (0.9 ** i)) * PV_K
            load_i = LOAD_PROF[t.month - 1, t.hour, we] + bias * (0.9 ** i)
            net_hat[i] = load_i - pv_i
        price_hat[:Hk] = prices
        co2_hat[:Hk] = co2s
        return price_hat, co2_hat, net_hat

    def _predict_lgbm(self, ts, tel, prices, co2s, wf, H, Hk):
        b = self._bundle
        pp = list(prices[:3]) + [prices[-1]] * max(0, 3 - len(prices[:3]))
        cc = list(co2s[:3]) + [co2s[-1]] * max(0, 3 - len(co2s[:3]))
        pp, cc = pp[:3], cc[:3]
        prof_p_k, prof_c_k = [], []
        for i in range(min(3, Hk)):
            t = ts + timedelta(hours=i)
            we = 1 if t.weekday() >= 5 else 0
            prof_p_k.append(float(b["price_prof"][t.month - 1, t.hour, we]))
            prof_c_k.append(float(b["co2_prof"][t.month - 1, t.hour, we]))
        ratio_p = float(np.clip(np.mean(pp) / max(np.mean(prof_p_k), 1e-6), 0.4, 1.8))
        ratio_c = float(np.clip(np.mean(cc) / max(np.mean(prof_c_k), 1e-6), 0.4, 1.8))

        load_last = self._safe(tel.get("ultim_consum_kw"), 1000.0)
        pv_last = self._safe(tel.get("ultima_solar_kw"), 0.0)
        irr_last = self._safe(tel.get("irradiancia_wm2"), 0.0)
        temp_a_last = self._safe(tel.get("temp_ambient_c"), 15.0)
        temp_p_last = self._safe(tel.get("temp_panel_c"), 15.0)
        vent_last = self._safe(tel.get("vent_ms"), 0.0)
        prev = ts - timedelta(hours=1)
        we_p = 1 if prev.weekday() >= 5 else 0
        lprof_prev = float(b["load_prof"][prev.month - 1, prev.hour, we_p])
        iprof_prev = float(b["irr_prof"][prev.month - 1, prev.hour])
        bias = float(np.clip(load_last - lprof_prev, -400, 400)) if lprof_prev > 100 else 0.0
        wf_eff = float(np.clip(irr_last / iprof_prev, 0.25, 1.25)) if iprof_prev > 50 else 1.0

        Xp, Xl, Xpv = [], [], []
        for i in range(H):
            t = ts + timedelta(hours=i)
            h = t.hour
            m = t.month
            we = 1 if t.weekday() >= 5 else 0
            sin_h = float(np.sin(2 * np.pi * h / 24))
            cos_h = float(np.cos(2 * np.pi * h / 24))
            if i >= Hk:
                Xp.append([m, h, we, i, sin_h, cos_h,
                           pp[0], pp[1], pp[2], cc[0], cc[1], cc[2],
                           float(b["price_prof"][m - 1, h, we]),
                           float(b["co2_prof"][m - 1, h, we]),
                           ratio_p, ratio_c])
            Xl.append([m, h, we, i, sin_h, cos_h,
                       load_last, pv_last, irr_last, bias, wf_eff,
                       float(b["load_prof"][m - 1, h, we]),
                       float(b["pv_prof"][m - 1, h]),
                       float(b["irr_prof"][m - 1, h])])
            Xpv.append([m, h, we, i, sin_h, cos_h,
                        load_last, pv_last, irr_last, wf_eff, temp_p_last, temp_a_last, vent_last,
                        float(b["pv_prof"][m - 1, h]), float(b["pv_prof_med"][m - 1, h]),
                        float(b["irr_prof"][m - 1, h])])

        price_hat = np.asarray(prices, float).copy()
        co2_hat = np.asarray(co2s, float).copy()
        if len(Xp):
            price_hat = np.concatenate([price_hat, b["price_model"].predict(np.array(Xp, float))])
            co2_hat = np.concatenate([co2_hat, b["co2_model"].predict(np.array(Xp, float))])
        price_hat = price_hat[:H]
        co2_hat = np.clip(co2_hat[:H], 0.0, 2.0)

        load_hat = b["load_model"].predict(np.array(Xl, float))
        pv_hat = b["pv_model"].predict(np.array(Xpv, float))
        net_hat = np.zeros(H)
        for i in range(H):
            t = ts + timedelta(hours=i)
            net_hat[i] = load_hat[i] - pv_hat[i]
        return price_hat, co2_hat, net_hat

    # --------------------------------------------------------------- LP
    def _solve_lp(self, net, w, soc, cap, power):
        net = np.asarray(net, float)
        w = np.asarray(w, float)
        n = len(w)
        if n == 0:
            return None
        scale = 1.0 / max(float(np.mean(np.abs(w))), 1e-12)
        ws = w * scale
        eps = EPS_LP * scale
        nv = 3 * n
        cost = np.zeros(nv)
        cost[2 * n:] = ws
        cost[:n] = eps
        cost[n:2 * n] = eps
        rows = np.arange(n)
        A = np.zeros((3 * n, nv))
        b = np.zeros(3 * n)
        A[rows, rows] = 1.0
        A[rows, n + rows] = -1.0
        A[rows, 2 * n + rows] = -1.0
        b[:n] = -net
        Lc = self.eta_c * np.tril(np.ones((n, n)))
        Ld = np.tril(np.ones((n, n))) / self.eta_d
        A[n:2 * n, :n] = Lc
        A[n:2 * n, n:2 * n] = -Ld
        b[n:2 * n] = cap - soc
        A[2 * n:3 * n, :n] = -Lc
        A[2 * n:3 * n, n:2 * n] = Ld
        b[2 * n:3 * n] = soc - self.soc_min
        bounds = [(0.0, power)] * n + [(0.0, power)] * n + [(0.0, None)] * n
        res = linprog(cost, A_ub=A, b_ub=b, bounds=bounds, method="highs")
        if not res.success or res.x is None:
            return None
        return float(res.x[0] - res.x[n])

    # -------------------------------------------------------------- acció
    def act(self, obs: dict) -> float:
        try:
            ts = self._parse_ts(obs.get("timestamp"))
            cap, power = self._read_dims(obs)
            soc = self._safe(obs.get("soc_kwh"), cap * 0.5)
            soc = min(max(soc, 0.0), cap)

            clock_ok = (self.last_ts is None) or (ts > self.last_ts)
            prices, co2s = self._window(obs)
            Hk = min(len(prices), len(co2s))
            if Hk == 0:
                return 0.0
            tel = obs.get("noves_dades_5min") or {}

            # hedge de dies d'entrenament (inert sota protocols de test-only)
            if self.precharge_gate and clock_ok and self._days_remaining(ts) > TEST_DAYS:
                if soc < cap - 1.0:
                    return self._clamp(power, soc, cap, power)
                return 0.0

            self._remember(ts, tel, prices, co2s)
            price_hat, co2_hat, net_hat = self._predict(ts, tel, prices, co2s)
            dco2, dcost = self._denominators(ts, tel, prices, co2s)
            w = 0.7 * np.asarray(co2_hat) / dco2 + 0.3 * np.asarray(price_hat) / dcost

            action = self._solve_lp(net_hat[:HORIZON], w[:HORIZON], soc, cap, power)
            if action is None:
                action = 0.0

            # guard de descàrrega contra el net previst de l'hora actual
            action = self._guard(action, net_hat[0], power)

            self.last_ts = ts
            return self._clamp(action, soc, cap, power)
        except Exception:
            return 0.0
